package main

import (
	"fmt"
	"sync"
	"time"
)

func greet(name string) {
	fmt.Println("你好，", name)
}

func main() {
	var wg sync.WaitGroup
	var mu sync.Mutex
	total := 0

	jobs := make(chan int, 3) // 带缓冲的 channel
	results := make(chan string, 3)

	// 两个 worker 并行处理任务
	for id := 1; id <= 2; id++ {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()
			for job := range jobs {
				results <- fmt.Sprintf("worker %d 完成任务 %d", id, job)
				mu.Lock()
				total++
				mu.Unlock()
			}
		}(id)
	}

	for job := 1; job <= 3; job++ {
		jobs <- job
	}
	close(jobs) // worker 的 range 收到关闭信号才会结束

	wg.Wait()
	close(results)

	for msg := range results {
		fmt.Println(msg)
	}
	fmt.Println("共完成", total, "个任务")

	// select：等完成信号，最多等 1 秒
	done := make(chan struct{})
	go func() {
		time.Sleep(100 * time.Millisecond)
		close(done)
	}()
	select {
	case <-done:
		fmt.Println("收到完成信号")
	case <-time.After(time.Second):
		fmt.Println("超时了")
	}

	go greet("并发世界")
	time.Sleep(50 * time.Millisecond)
}
